import Image from "next/image";

type DitheredProps = {
  src: string;
  width: number;
  height: number;
  className?: string;
  style?: React.CSSProperties;
};

/**
 * A 1-bit dithered illustration (generated by scripts/prepare-assets.mjs).
 * Served unoptimised: lossy re-encoding would smear the dither pattern.
 * Purely decorative, so it's hidden from assistive technology.
 */
export function Dithered({ src, width, height, className = "", style }: DitheredProps) {
  return (
    <Image
      src={src}
      width={width}
      height={height}
      alt=""
      aria-hidden="true"
      unoptimized
      className={`px h-auto ${className}`}
      style={style}
    />
  );
}
